"use client";

import React, {
  createContext,
  useEffect,
  useState,
  ReactNode,
  useMemo,
} from "react";

import { AuthService } from "@/application/auth/AuthService";
import { FirebaseAuthClient } from "@/infrastructure/auth/FirebaseAuthClient";
import { LaravelAuthApi } from "@/infrastructure/auth/LaravelAuthApi";
import { createHttpClient } from "@/infrastructure/auth/HttpClient";
import { TokenRefreshService } from "@/application/auth/TokenRefreshService";
import { AuthUser } from "@/domain/auth/AuthUser";

// ★ 型を export しないことで Next の "use client" 制限を回避
export const AuthContext = createContext<any>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // -------------------------------------------------------------
  // ✔ サービスの初期化は useMemo で1回だけ実行（DDDにおける Singleton 代わり）
  // -------------------------------------------------------------
  const { authService, laravelApi, refreshService } = useMemo(() => {
    const firebase = new FirebaseAuthClient();
    const httpClient = createHttpClient(async () => {
      const refreshed = await refresh.refresh();
      if (refreshed) {
        setUser(refreshed);
      } else {
        setUser(null);
      }
    });

    const laravel = new LaravelAuthApi(httpClient);
    const auth = new AuthService(firebase, laravel);
    const refresh = new TokenRefreshService(laravel);

    return {
      authService: auth,
      laravelApi: laravel,
      refreshService: refresh,
    };
  }, []);

  // -------------------------------------------------------------
  // 🔥 初回ロード（/me 復元）
  // -------------------------------------------------------------
  useEffect(() => {
    (async () => {
      try {
        const u = await laravelApi.me();
        setUser(u);
      } catch {
        setUser(null);
      } finally {
        setIsLoading(false);
      }
    })();
  }, [laravelApi]);

  // -------------------------------------------------------------
  // 認証操作
  // -------------------------------------------------------------
  async function register({
    name,
    email,
    password,
  }: {
    name: string;
    email: string;
    password: string;
  }) {
    return authService.register(name, email, password);
  }

  async function login({
    email,
    password,
  }: {
    email: string;
    password: string;
  }) {
    setIsLoading(true);
    const u = await authService.login(email, password);
    setUser(u);
    setIsLoading(false);
  }

  async function logout() {
    await authService.logout();
    setUser(null);
  }

  async function reloadUser() {
    try {
      const u = await laravelApi.me();
      setUser(u);
    } catch {
      setUser(null);
    }
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        register,
        login,
        logout,
        reloadUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}
